"""Offline real-Chromium visual test of HTML generated by GramOS admin renderer.
Run `node tests/render-v5-admin.mjs` first. No navigation or live auth.
"""
from pathlib import Path
from playwright.sync_api import sync_playwright
root=Path(__file__).resolve().parent/'screenshots-v5'
with sync_playwright() as p:
 browser=p.chromium.launch(headless=True,executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 for width,height,mode in [(1366,900,'desktop'),(390,844,'phone')]:
  page=browser.new_page(viewport={'width':width,'height':height},device_scale_factor=1)
  for section in ['dashboard','content','import','overview']:
   page.set_content((root/(section+'.html')).read_text(),wait_until='domcontentloaded')
   assert page.locator('main').count()>=1,(mode,section,'missing main')
   if section=='dashboard':
    assert page.locator('[data-gx-shortcut]').count()==7,(mode,'missing quick links')
    assert page.locator('.gx-timeline').count()>0,(mode,'missing activity history')
   if section=='content':assert page.locator('[data-action="delete-item"]').count()>0,(mode,'missing remove action')
   if section=='import':assert page.locator('input[data-gx-csv-input]').count()>0,(mode,'missing importer')
   horizontal=page.evaluate('({scroll:document.documentElement.scrollWidth, viewport:document.documentElement.clientWidth})')
   # A few tables intentionally scroll inside their own containers; the document must stay within viewport.
   if horizontal['scroll']>width+3:print('WARN horizontal overflow',mode,section,horizontal)
   page.screenshot(path=str(root/(f'{mode}-{section}.png')),full_page=True)
   print('PASS visual',mode,section,'widths',horizontal)
  page.close()
 browser.close()
